{"hypotheses": [
  {
    "name": "Hypothesis_1",
    "mechanism": "Combination of low illiquidity and high asset growth signals fundamentally strong firms that are not fully discovered by the market yet. This should lead to excess returns when the market adjusts for the undiscovered values.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AssetGrowth"},
        {"weight": -0.5, "primitive": "Illiquidity"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.5,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "Hypothesis_2",
    "mechanism": "A composite of high momentum and low leverage may signal companies undergoing positive growth changes that are not yet fully priced in by the market.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Mom12m"},
        {"weight": -0.5, "primitive": "Leverage"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Hypothesis_3",
    "mechanism": "Firms with a high book-to-market ratio and low bid-ask spread are undervalued and more liquid, suggesting they may be poised for a price correction.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": -0.5, "primitive": "BidAskSpread"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Hypothesis_4",
    "mechanism": "Low asset growth and high book leverage may indicate companies with deteriorating fundamentals, resulting in negative returns.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AssetGrowth"},
        {"weight": 0.5, "primitive": "BookLeverage"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "lower"},
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "above", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": -0.5,
    "expected_decay_half_life_months": null
  },
  {
    "name": "Hypothesis_5",
    "mechanism": "High advertising expense and low price suggest a firm is investing in growth while still remaining undervalued, leading to positive returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AdExp"},
        {"weight": -0.5, "primitive": "Price"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "AdExp", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.4,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Hypothesis_6",
    "mechanism": "Firms with high EPS forecast revisions and low short interest might be undervalued and less prone to negative shocks, resulting in positive future returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AnalystRevision"},
        {"weight": -0.5, "primitive": "ShortInterest"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Hypothesis_7",
    "mechanism": "High gross profits and low bid-ask spread may indicate profitable and liquid companies, leading to excess returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "GP"},
        {"weight": -0.5, "primitive": "BidAskSpread"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "correlation", "primitive": "GP", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "Hypothesis_8",
    "mechanism": "Firms with high sales-to-price ratio and low illiquidity are undervalued and have good liquidity, leading to positive future returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "SP"},
        {"weight": -0.5, "primitive": "Illiquidity"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "SP", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 18
  }
]}
